function compileTemplate(template) {
  const tokens = [];
  const re = /\{\{(.*?)\}\}/g;
  let last = 0, match;
  while ((match = re.exec(template)) !== null) {
    if (match.index > last) tokens.push({ type: 'text', value: template.slice(last, match.index) });
    tokens.push({ type: 'expr', value: match[1].trim() });
    last = match.index + match[0].length;
  }
  if (last < template.length) tokens.push({ type: 'text', value: template.slice(last) });
  return ctx => tokens.map(t =>
    t.type === 'text' ? t.value : new Function('ctx', `with(ctx){return ${t.value}}`)(ctx)
  ).join('');
}

