  function* object() { eat('{'); ws(); yield {}; while (peek() !== '}') { yield* string(); ws(); eat(':'); yield* value(); ws(); if (peek() === ',') i++; ws(); } eat('}'); }
  yield* value();
}

class PersistentVector {
  static BITS = 5;
  static SIZE = 1 << PersistentVector.BITS;
  static MASK = PersistentVector.SIZE - 1;

  constructor(size = 0, root = null, tail = []) {
    this.size = size;
    this.root = root;
    this.tail = tail;
  }

  push(val) {
    if (this.tail.length < PersistentVector.SIZE) {
      return new PersistentVector(this.size + 1, this.root, [...this.tail, val]);
    }
    const newRoot = this._pushTail(this.root, this.tail, this._depth());
    return new PersistentVector(this.size + 1, newRoot, [val]);
  }

  get(idx) {
    if (idx >= this.size - this.tail.length) {
      return this.tail[idx - (this.size - this.tail.length)];
    }
    let node = this.root;
    for (let level = this._depth() - 1; level >= 0; level--) {
      node = node[(idx >> (level * PersistentVector.BITS)) & PersistentVector.MASK];
    }
    return node[idx & PersistentVector.MASK];
  }

  _depth() {
    return Math.max(1, Math.ceil(Math.log(this.size || 1) / Math.log(PersistentVector.SIZE)));
  }

  _pushTail(node, tail, depth) {
    if (depth === 1) return [...(node || []), tail];
    const path = [...(node || [new Array(PersistentVector.SIZE)])];
    path[path.length - 1] = this._pushTail(path[path.length - 1], tail, depth - 1);
    return path;
  }
}

