function createVirtualDOM(type, props, ...children) {
  return { type, props: props ?? {}, children: children.flat() };
}

function diff(oldNode, newNode) {
  if (!oldNode) return { type: 'CREATE', node: newNode };
  if (!newNode) return { type: 'REMOVE' };
  if (typeof oldNode !== typeof newNode || oldNode.type !== newNode.type) {
    return { type: 'REPLACE', node: newNode };
  }
  if (typeof newNode === 'string') {
    return oldNode !== newNode ? { type: 'TEXT', value: newNode } : null;
  }
  const propPatches = diffProps(oldNode.props, newNode.props);
  const childPatches = diffChildren(oldNode.children, newNode.children);
  return (propPatches.length || childPatches.some(Boolean)) ? { type: 'UPDATE', propPatches, childPatches } : null;
}

function diffProps(oldProps, newProps) {
  const all = new Set([...Object.keys(oldProps), ...Object.keys(newProps)]);
  return [...all]
    .filter(key => oldProps[key] !== newProps[key])
    .map(key => ({ key, value: newProps[key] }));
}

function diffChildren(oldCh = [], newCh = []) {
  const len = Math.max(oldCh.length, newCh.length);
  return Array.from({ length: len }, (_, i) => diff(oldCh[i], newCh[i]));
}

class WorkerPool {
  constructor(workerFactory, size) {
    this.workers = Array.from({ length: size }, workerFactory);
    this.queue = [];
    this.idle = [...this.workers];
  }

  run(task) {
    return new Promise((resolve, reject) => {
      const execute = worker => {
        this.idle = this.idle.filter(w => w !== worker);
        Promise.resolve(task(worker))
          .then(result => {
            resolve(result);
            this.idle.push(worker);
            if (this.queue.length) {
              const next = this.queue.shift();
              execute(this.idle[this.idle.length - 1]);
              next();
            }
          })
          .catch(err => {
            reject(err);
            this.idle.push(worker);
          });
      };

      if (this.idle.length > 0) {
        execute(this.idle[this.idle.length - 1]);
      } else {
        this.queue.push(() => execute(this.idle[this.idle.length - 1]));
      }
    });
  }

  drain() {
    return Promise.all(this.workers.map(w =>
      new Promise(resolve => {
        const check = () => this.idle.includes(w) ? resolve() : setTimeout(check, 10);
        check();
      })
    ));
  }
}
